// LoadHousehold loads the idempotencyKey's Household into the .R struct
func (o *IdempotencyKey) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.IdempotencyKeys = IdempotencyKeySlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the idempotencyKey's Household into the .R struct
func (os IdempotencyKeySlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	idempotencyKeyByKey := make(map[uuid.UUID][]*IdempotencyKey, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		idempotencyKeyByKey[o.HouseholdID] = append(idempotencyKeyByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := idempotencyKeyByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.IdempotencyKeys = append(rel.R.IdempotencyKeys, o)

			o.R.Household = rel

		}
	}

	return nil
}

type idempotencyKeyJoins[Q dialect.Joinable] struct {
	typ       string
	Household modAs[Q, householdColumns]
}

func (j idempotencyKeyJoins[Q]) aliasedAs(alias string) idempotencyKeyJoins[Q] {
	return buildIdempotencyKeyJoins[Q](buildIdempotencyKeyColumns(alias), j.typ)
}

func buildIdempotencyKeyJoins[Q dialect.Joinable](cols idempotencyKeyColumns, typ string) idempotencyKeyJoins[Q] {
	return idempotencyKeyJoins[Q]{
		typ: typ,
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
